<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import{Calendar,Document,Plus,Search}from'@element-plus/icons-vue';import{getNewsList,publishNews}from'@/api/news';
const route=useRoute(),loading=ref(false),dialog=ref(false),keyword=ref(''),category=ref(String(route.query.category||'all')),selected=ref<any>(),items=ref<any[]>([]);const fallback=[{id:1,title:'校园充电设施服务时间调整通知',summary:'为进一步提升校园充电服务质量，部分区域服务时间将进行调整。',category:'policy',date:'2026-07-12',content:'校园充电设施将继续优化运行安排，请师生根据页面实时状态合理规划充电时间。'},{id:2,title:'绿色出行主题活动开始报名',summary:'参与校园绿色出行活动，共建低碳校园。',category:'event',date:'2026-07-10',content:'本次活动面向全校师生开放，欢迎关注校园充电服务平台后续通知。'},{id:3,title:'充电区域安全使用提示',summary:'请规范停放车辆，并在充电结束后及时移走。',category:'policy',date:'2026-07-08',content:'连接充电设备前请检查接口状态，发现设备异常请停止使用并联系管理员。'}];const filtered=computed(()=>items.value.filter(n=>(category.value==='all'||n.category===category.value||n.newsCategory===category.value)&&(!keyword.value||`${n.title}${n.summary}`.includes(keyword.value))));const form=reactive({title:'',content:'',newsCategory:'event'});onMounted(async()=>{loading.value=true;try{const r:any=await getNewsList();items.value=Array.isArray(r?.data)&&r.data.length?r.data:fallback}catch{items.value=fallback}finally{loading.value=false}});const publish=async()=>{if(!form.title||!form.content){ElMessage.warning('请填写标题和正文');return}try{await publishNews({title:form.title,content:form.content,categoryId:form.newsCategory==='event'?1:2,imageUrl:'',publishDate:new Date().toISOString().slice(0,10),newsCategory:form.newsCategory});items.value.unshift({id:Date.now(),...form,date:new Date().toISOString().slice(0,10),summary:form.content.slice(0,60),category:form.newsCategory});dialog.value=false;ElMessage.success('资讯发布成功')}catch{ElMessage.error('发布失败，请稍后重试')}}
</script>
<template><div class="news-page"><header class="page-header news-header"><div><p>CAMPUS NEWS</p><h1>校园资讯</h1><span>服务通知、校园活动与安全提示</span></div><el-button v-if="route.query.mode==='publish'" type="primary" :icon="Plus" @click="dialog=true">发布资讯</el-button></header><main class="news-main"><section class="news-tools"><el-segmented v-model="category" :options="[{label:'全部',value:'all'},{label:'校园活动',value:'event'},{label:'通知政策',value:'policy'},{label:'失物招领',value:'lost'}]"/><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="搜索资讯"/></section><section v-loading="loading" class="news-grid"><article v-for="n in filtered" :key="n.id" @click="selected=n"><span class="news-icon"><Document/></span><span class="category">{{n.category==='event'?'校园活动':n.category==='lost'?'失物招领':'通知政策'}}</span><h2>{{n.title}}</h2><p>{{n.summary||String(n.content||'').replace(/<[^>]+>/g,'').slice(0,90)}}</p><footer><span><Calendar/>{{n.date||n.publishDate||'近期'}}</span><b>阅读全文</b></footer></article><el-empty v-if="!loading&&!filtered.length" description="暂无相关资讯"/></section></main><el-dialog v-model="selected" :title="selected?.title" width="650px"><div class="article-content" v-html="selected?.content||selected?.summary"/></el-dialog><el-dialog v-model="dialog" title="发布校园资讯" width="580px"><el-form label-position="top"><el-form-item label="资讯标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="分类"><el-select v-model="form.newsCategory"><el-option label="校园活动" value="event"/><el-option label="通知政策" value="policy"/><el-option label="失物招领" value="lost"/></el-select></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="8"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="publish">确认发布</el-button></template></el-dialog></div></template>
<style scoped>.news-page{min-height:calc(100vh - 72px);padding-bottom:40px;background:var(--surface-muted)}.news-header{display:flex;align-items:flex-end;justify-content:space-between}.news-header p,.news-header h1,.news-header span{margin:0}.news-header p{color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.11em}.news-header h1{margin:7px 0 9px}.news-header span{color:var(--text-secondary)}.news-tools{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:20px}.news-tools .el-input{max-width:280px}.news-grid{min-height:240px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.news-grid article{position:relative;padding:23px;background:#fff;border:1px solid var(--border-color);border-radius:18px;box-shadow:var(--shadow-sm);cursor:pointer;transition:.2s}.news-grid article:hover{transform:translateY(-3px);border-color:var(--border-hover);box-shadow:var(--shadow-md)}.news-icon{width:42px;height:42px;display:grid;place-items:center;color:var(--brand);background:var(--brand-soft);border-radius:12px}.news-icon :deep(svg){width:21px}.category{position:absolute;right:20px;top:22px;padding:5px 9px;color:var(--brand);background:var(--brand-soft);border-radius:99px;font-size:10px;font-weight:750}.news-grid h2{margin:23px 0 10px;font-size:18px;line-height:1.45}.news-grid p{min-height:66px;margin:0;color:var(--text-secondary);font-size:12px;line-height:1.8}.news-grid footer{display:flex;justify-content:space-between;align-items:center;margin-top:22px;padding-top:15px;border-top:1px solid #edf1ee;font-size:10px}.news-grid footer span{display:flex;align-items:center;gap:5px;color:var(--text-muted)}.news-grid footer span :deep(svg){width:12px}.news-grid footer b{color:var(--brand)}.article-content{color:var(--text-secondary);line-height:1.9}.news-tools :deep(.el-segmented){overflow:auto}@media(max-width:900px){.news-grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.news-header,.news-tools{align-items:stretch;flex-direction:column}.news-tools .el-input{max-width:none}.news-grid{grid-template-columns:1fr}}</style>
